const res = $input.first().json;
const body = res.body ?? res;

console.log('[Wariskan Cron] weekly-report result:');
console.log(JSON.stringify(body, null, 2));

if (!body.success) {
  console.error('[Wariskan Cron] weekly-report job failed:', body.error);
}

const summary = {
  date: new Date().toISOString(),
  reportsSent: body.processedCount ?? 0,
  skipped: body.skippedCount ?? 0,
  errors: body.errors?.length ?? 0,
  durationMs: body.durationMs ?? null,
};

console.log('[Wariskan Cron] Weekly report run complete:', JSON.stringify(summary));
return [{ json: summary }];
